PREFIX ssi: <https://ligm.univ-eiffel.fr/twinhypervisor/ssi#>
PREFIX bot: <https://w3id.org/bot#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
SELECT (SUM(?surf) AS ?total) WHERE {
        ?s a bot:Space ; rdfs:label ?nom ; ssi:area ?surf . FILTER STRSTARTS(?nom, "A") }

PREFIX ssi: <https://ligm.univ-eiffel.fr/twinhypervisor/ssi#>
PREFIX bot: <https://w3id.org/bot#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
SELECT ?gid WHERE {
        ?n rdfs:label "Level 2" ; bot:hasSpace ?s . ?s ssi:ifcGlobalId ?gid .
        { SELECT ?s (COUNT(DISTINCT ?p) AS ?nb) WHERE { ?p a ssi:Door ; ssi:connects ?s } GROUP BY ?s }
        FILTER (?nb = 1) }

PREFIX ssi: <https://ligm.univ-eiffel.fr/twinhypervisor/ssi#>
PREFIX bot: <https://w3id.org/bot#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
SELECT DISTINCT ?gid WHERE {
        { ?s bot:containsElement ?e . ?e a ssi:Stair }
        UNION { ?e a ssi:Stair ; ssi:linksSpace ?s . FILTER NOT EXISTS { ?c bot:containsElement ?e } }
        ?s ssi:ifcGlobalId ?gid }

PREFIX ssi: <https://ligm.univ-eiffel.fr/twinhypervisor/ssi#>
PREFIX bot: <https://w3id.org/bot#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
SELECT ?gid WHERE {
        ?s ssi:inDwelling ?z ; ssi:area ?surf ; ssi:ifcGlobalId ?gid .
        { SELECT ?z (MAX(?a) AS ?max) WHERE { ?x ssi:inDwelling ?z ; ssi:area ?a } GROUP BY ?z }
        FILTER (?surf = ?max) }

PREFIX ssi: <https://ligm.univ-eiffel.fr/twinhypervisor/ssi#>
PREFIX bot: <https://w3id.org/bot#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
SELECT DISTINCT ?gid WHERE {
        ?a ssi:inDwelling ?za . ?b ssi:inDwelling ?zb . ?za rdfs:label "Logement A" . ?zb rdfs:label "Logement B" .
        ?d a ssi:EvacuationDistance ; ssi:from ?a ; ssi:to ?b .
        OPTIONAL { ?d ssi:viaElement ?e . ?e ssi:ifcGlobalId ?eg }
        BIND (COALESCE(?eg, CONCAT("ouverture:", STR(?a), "|", STR(?b))) AS ?gid) }

PREFIX ssi: <https://ligm.univ-eiffel.fr/twinhypervisor/ssi#>
PREFIX bot: <https://w3id.org/bot#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
SELECT ?gid WHERE {
        ?o sosa:hasFeatureOfInterest ?s ; sosa:observedProperty ssi:Occupancy ; sosa:hasSimpleResult ?n ; ssi:scenarioTime ?t .
        { SELECT ?s (MAX(?t2) AS ?dernier) WHERE {
             ?o2 sosa:hasFeatureOfInterest ?s ; sosa:observedProperty ssi:Occupancy ; ssi:scenarioTime ?t2 . FILTER (?t2 <= 300) }
           GROUP BY ?s }
        FILTER (?t = ?dernier && ?n > 0)
        ?s ssi:ifcGlobalId ?gid }
